"""Second revision, Section 3. Secondary analyses under the reference model generated by inversion,
and the negative control for the primary family.

  multiscale  D_W at W = 100, 1,000 and 5,000, each against R realizations of the reference model
              built with the resolution S that the simulation-only rule of script 13 assigns to that
              window (W=100 -> S=20,000; W=1,000 -> S=2,000; W=5,000 -> S=1,000). The rule assigns no
              resolution to W=20,000, which is therefore reported descriptively and not tested.
              Holm's adjustment over the three windows.
  decades     D_1000, D_ratio and the mean ratio inside each decade from 10^12 to 10^18, each decade
              with its own reference model (intensity from the gaps of that decade alone, S = 20,000 or
              half the gaps of the decade when it has fewer than 40,000), R realizations by inversion.
              Holm's adjustment over the six decades, separately for each statistic.
  lattice     the near-lattice negative control (independent gaps of mean 1 and standard deviation
              0.15, truncated at 1e-9, multiplied by m_S(i), S = 20,000) evaluated on the five primary
              statistics, against the null distributions of script 11b.

Usage: python code/20_secondary_inversion.py [R] [workers]
"""
import json, os, sys, time
from multiprocessing import Pool
import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import benchmark as B
from common import RESULTS, census_cache

R = int(sys.argv[1]) if len(sys.argv) > 1 else 1000
WORKERS = int(sys.argv[2]) if len(sys.argv) > 2 else 4
SEED = 20261011
RULE = {100: 20000, 1000: 2000, 5000: 1000}
K = 40


def holm(ps):
    ps = np.asarray(ps, float); m = len(ps)
    order = np.argsort(ps); out = np.empty(m); run = 0.0
    for rank, i in enumerate(order):
        run = max(run, min(1.0, (m - rank) * ps[i])); out[i] = run
    return out


def ms_work(task):
    seed, W, reps = task
    n, _ = census_cache()
    pos = n.astype(np.float64)
    xk, Lk = B.cumulative_intensity(pos, RULE[W])
    rng = np.random.default_rng(seed)
    out = []
    for _ in range(reps):
        g = B.gen_inverse(xk, Lk, len(pos), rng)
        out.append(B.sup_dev(g / B.rollmean(g, W), B.exp_cdf))
    return W, out


def dec_work(task):
    seed, k, reps = task
    n, _ = census_cache()
    sub = n[(n >= 10 ** k) & (n < 10 ** (k + 1))].astype(np.float64)
    S = min(20000, (len(sub) - 1) // 2)
    xk, Lk = B.cumulative_intensity(sub, S)
    rng = np.random.default_rng(seed)
    out = []
    for _ in range(reps):
        g = B.gen_inverse(xk, Lk, len(sub), rng)
        q = B.ratios(g)
        out.append([B.sup_dev(g / B.rollmean(g, 1000), B.exp_cdf), B.sup_dev(q, B.ratio_cdf), float(q.mean())])
    return k, out


def main():
    t0 = time.time()
    n, _ = census_cache()
    pos = n.astype(np.float64)
    g = np.diff(pos)
    seq = np.random.SeedSequence(SEED)
    res = dict(R=R, seed=SEED, rule=RULE)

    # ---------------------------------------------------------------- multiscale
    tasks = [(c.generate_state(1)[0], W, 10) for W in RULE for c in seq.spawn(R // 10)]
    null = {W: [] for W in RULE}
    with Pool(WORKERS) as pool:
        for i, (W, v) in enumerate(pool.imap_unordered(ms_work, tasks)):
            null[W] += v
            if i % 50 == 0:
                print(f"  multiscale {i+1}/{len(tasks)} at {time.time()-t0:.0f}s", flush=True)
    ms = {}
    for W in RULE:
        d = np.array(null[W]); obs = B.sup_dev(g / B.rollmean(g, W), B.exp_cdf)
        p = B.mc_pvalue(obs, d, False)
        ms[W] = dict(S=RULE[W], obs=obs, null_mean=float(d.mean()), q95=float(np.quantile(d, .95)), p=float(p),
                     p_se=B.mc_se(p, len(d)), R=len(d))
    for W, h in zip(RULE, holm([ms[W]["p"] for W in RULE])):
        ms[W]["p_holm"] = float(h)
    res["multiscale"] = {str(W): v for W, v in ms.items()}
    res["multiscale_W20000_descriptive"] = dict(obs=B.sup_dev(g / B.rollmean(g, 20000), B.exp_cdf),
                                                note="no resolution S in the grid gives a valid level at W=20,000 (script 13)")
    for W, v in ms.items():
        print(f"W={W:5d} S={v['S']:5d} D={v['obs']:.6f} null mean={v['null_mean']:.6f} q95={v['q95']:.6f} "
              f"p={v['p']:.4f} holm={v['p_holm']:.4f}", flush=True)

    # ---------------------------------------------------------------- decades
    ks = list(range(12, 18))
    seq2 = np.random.SeedSequence([SEED, 2])
    tasks = [(c.generate_state(1)[0], k, 10) for k in ks for c in seq2.spawn(R // 10)]
    dnull = {k: [] for k in ks}
    with Pool(WORKERS) as pool:
        for i, (k, v) in enumerate(pool.imap_unordered(dec_work, tasks)):
            dnull[k] += v
            if i % 50 == 0:
                print(f"  decades {i+1}/{len(tasks)} at {time.time()-t0:.0f}s", flush=True)
    dec = {}
    names = ["D_1000", "D_ratio", "m_ratio"]
    for k in ks:
        sub = n[(n >= 10 ** k) & (n < 10 ** (k + 1))].astype(np.float64)
        gs = np.diff(sub); u = gs / B.rollmean(gs, 1000); q = B.ratios(gs)
        o = [B.sup_dev(u, B.exp_cdf), B.sup_dev(q, B.ratio_cdf), float(q.mean())]
        d = np.array(dnull[k])
        dec[k] = dict(count=int(len(sub)), mean=float(u.mean()), sd=float(u.std()), median=float(np.median(u)), R=len(d),
                      stats={nm: dict(obs=o[j], q95=float(np.quantile(d[:, j], .95)) if j < 2 else None,
                                      p=float(B.mc_pvalue(o[j], d[:, j], j == 2))) for j, nm in enumerate(names)})
    for nm in names:
        for k, h in zip(ks, holm([dec[k]["stats"][nm]["p"] for k in ks])):
            dec[k]["stats"][nm]["p_holm"] = float(h)
    res["decades"] = {f"1e{k}-1e{k+1}": v for k, v in dec.items()}
    for k, v in dec.items():
        print(f"1e{k}-1e{k+1} n={v['count']:7d} " + "  ".join(
            f"{nm}={s['obs']:.6f} p={s['p']:.3f} holm={s['p_holm']:.3f}" for nm, s in v["stats"].items()), flush=True)

    # ---------------------------------------------------------------- lattice control
    z = np.load(os.path.join(RESULTS, "11b_primary_family.npz"))
    D = z["null"]
    mu, sd = D[:, 4:].mean(0), D[:, 4:].std(0)
    rng = np.random.default_rng([SEED, 3])
    lam = B.rollmean(g, 20000)
    gl = np.clip(rng.normal(1.0, 0.15, size=len(g)), 1e-9, None) * lam
    q = B.ratios(gl)
    zq = (B.rank_acf(q) - mu) / sd
    lat = dict(D_1000=B.sup_dev(gl / B.rollmean(gl, 1000), B.exp_cdf), D_ratio=B.sup_dev(q, B.ratio_cdf),
               m_ratio=float(q.mean()), D_cf=B.cross_fit(gl, rng, splits=K), Q_10=float(np.sum(zq ** 2)))
    Qn = np.sum(((D[:, 4:] - mu) / sd) ** 2, axis=1)
    cols = dict(D_1000=D[:, 0], D_ratio=D[:, 1], m_ratio=D[:, 2], D_cf=D[:, 3], Q_10=Qn)
    res["lattice"] = {k: dict(value=float(v), p=float(B.mc_pvalue(v, cols[k], k == "m_ratio"))) for k, v in lat.items()}
    print("lattice", {k: (round(v["value"], 4), round(v["p"], 4)) for k, v in res["lattice"].items()}, flush=True)

    res["elapsed_s"] = time.time() - t0
    with open(os.path.join(RESULTS, "20_secondary_inversion.json"), "w") as fh:
        json.dump(res, fh, indent=1)
    print(f"done in {res['elapsed_s']:.0f}s")


if __name__ == "__main__":
    main()
